			/*
			 * "저장" / "수정" 버튼(btnCmntRev)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnCmntRevClick(e){
			    var btnCmntRev = e.control;
			    
			    var idx = btnCmntRev.userData("idx");
			    var txaId = btnCmntRev.userData("tx");
			    
			    var vcRplyTxa = app.lookup(txaId);
			    
			    var revise_BtnId = btnCmntRev.userData("revise2");
			    var delete_BtnId = app.lookup("btnDelete2"+idx).id;
			    
			    if(btnCmntRev.value =="저장"){
			        var rplyCn = vcRplyTxa.value;
			        
			        if (rplyCn.length == 0 || rplyCn.trim() == "") {
			        
			            util.Msg.alert(app, "내용을 입력해주세요.", null, function() {
			                vcRplyTxa.focus();
			            });
			            
			        } else {
			            
			            util.DataSet.setValue(app, "dsReply", idx, "CMNT_CN", rplyCn);
			            
			            // 저장 서브미션 호출
			            util.Submit.send(app, "subReplySave", function(pbSuccess) {
			                if (pbSuccess) {
			                    
			                    util.Control.setReadOnly(app, true, txaId);
			                    
			                    util.Control.setValue(app, revise_BtnId, "수정");
			                    util.Control.setValue(app, delete_BtnId, "삭제");
			                    
			                    doRplyList();
			                }
			            });
			        }
			    } else if (btnCmntRev.value == "수정") {
			        
			        util.Control.setReadOnly(app, false, txaId);
			        
			        util.Control.setValue(app, revise_BtnId, "저장");
			        util.Control.setValue(app, delete_BtnId, "취소");
			        
			        util.Control.setFocus(app, txaId);
			    }
			}

