			    var dsRplyList = app.lookup("dsReply");
			    var vcRplyTxa = app.lookup(txaId);
			    
			    var revise_BtnId = app.lookup("btnRevise2"+idx).id;
			    var delete_BtnId = btnCmntDel.userData("btnDeleteId");
			    
